# Fuck if I know if this is accurate :)

.include "macros.S"

.ifdef glitch2m
# =================================================================================
# This is a glitch2m patch set for corona WB, as generated by modern-loadfare:
# python3 loadfare.py --im-a-developer --nofuse --nopost --write-xebuild cbb\cbb_13182.bin output\cbb_13182_patchlist.bin
# exactly the same patches as winchy, there's minimal difference between 13182 and 16128
# =================================================================================
MAKEPATCH 0x000004FC
0:
	nop
9:

MAKEPATCH 0x00006A18
0:
	addi %r11, %r29, -0x660
	cmplwi cr6, %r11, 0xf9a0
9:

MAKEPATCH 0x00006A34
0:
	cmplwi cr6, %r22, 0x260
9:

MAKEPATCH 0x00006C14
0:
	addis %r31, %r22, 0x400
	MAKEBRANCH 0x6C74
9:

MAKEPATCH 0x00006E60
0:
	blr
9:

MAKEPATCH 0x000086A0
0:
	li %r3, -1
	blr
9:
.else
# adding POST codes back???? who actually cares about this anymore
MAKEPATCH 0x000003EC
0:
	li %r3, 0x200
	oris %r3, %r3, 0x8000
	sldi %r3, %r3, 0x20
	oris %r3, %r3, 6
	li %r4, 0x20
	sldi %r4, %r4, 0x38
	std %r4, 0x1010(%r3)
	MAKEBRANCH 0x6314
9:

MAKEPATCH 0x00000E30
0:
	MAKEBRANCH 0x62FC
9:

# =================================================================================
#;  skips check on patch slots
# =================================================================================
MAKEPATCH 0x000062D0
0:
	MAKEBRANCH 0x63C4
9:

MAKEPATCH 0x000062FC
0:
	li %r3, 0x300
	li %r6, 0x4000
	rotldi %r6, %r6, 0xc
	addi %r6, %r6, 0x300
	clrlwi %r3, %r3, 0x10
	MAKEBRANCH 0xE34

	li %r1, 0x200
	oris %r1, %r1, 0x8000
	sldi %r1, %r1, 0x20
	oris %r1, %r1, 1
	ori %r1, %r1, 0xf300

	li %r2, 0x200
	oris %r2, %r2, 0x8000
	sldi %r2, %r2, 0x20
	MAKEBRANCH 0x40C
9:

#;============================================================================
#;  force zeropair/skip smc hash check
#;============================================================================
MAKEPATCH 0x00006448
0:
	nop
9:

#;============================================================================
#;  disable check on CD header
#;============================================================================
MAKEPATCH 0x00006A78
0:
	nop
9:

#;============================================================================
#;  disable SHA_VERIFY_4BL pseudo-memdiff
#;============================================================================
MAKEPATCH 0x00006B84
0:
	li %r3, -1
9:
.endif

